"""Embedded base64 assets for BanTRel.

This module provides base64-encoded binary assets (logo and favicon) and a
helper function ensure_assets() to automatically extract them to the local
assets/ directory upon application startup. This completely prevents Git LFS /
Xet binary upload rejections when deploying to Hugging Face Spaces.
"""

import base64
import os

LOGO_B64 = ""
FAVICON_B64 = ""

LOGO_DATA_URI = f"data:image/png;base64,{LOGO_B64}"
FAVICON_DATA_URI = f"data:image/x-icon;base64,{FAVICON_B64}"


def ensure_assets(base_dir=None):
    """Ensure logo.png and favicon.ico exist in the assets directory.

    Extracts the embedded base64 assets if they are missing on disk.
    """
    if base_dir is None:
        base_dir = os.path.dirname(os.path.abspath(__file__))
    assets_dir = os.path.join(base_dir, "assets")
    os.makedirs(assets_dir, exist_ok=True)

    logo_path = os.path.join(assets_dir, "logo.png")
    if not os.path.exists(logo_path) or os.path.getsize(logo_path) == 0:
        try:
            with open(logo_path, "wb") as f_out:
                f_out.write(base64.b64decode(LOGO_B64))
        except Exception as e:
            print(f"[BanTRel] Warning: failed to write {logo_path}: {e}")

    favicon_path = os.path.join(assets_dir, "favicon.ico")
    if not os.path.exists(favicon_path) or os.path.getsize(favicon_path) == 0:
        try:
            with open(favicon_path, "wb") as f_out:
                f_out.write(base64.b64decode(FAVICON_B64))
        except Exception as e:
            print(f"[BanTRel] Warning: failed to write {favicon_path}: {e}")
